import{_ as e,o as i,c as t,a0 as c}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Skill: /business-process","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/business-process.md","filePath":"references/skills/business-process.md"}'),o={name:"references/skills/business-process.md"};function a(s,n,r,l,h,u){return i(),t("div",null,[...n[0]||(n[0]=[c('<h1 id="skill-business-process" tabindex="-1">Skill: <code>/business-process</code> <a class="header-anchor" href="#skill-business-process" aria-label="Permalink to &quot;Skill: `/business-process`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>business-process</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/business-process</code></li><li>Thường dùng kèm với các cụm từ điều hướng như <code>/common</code> hoặc <code>/surfaces</code> để xác định ngữ cảnh vẽ luồng nghiệp vụ.</li><li>Dùng cờ <code>/legacy</code> để đào xới lại quy trình từ mã nguồn cũ.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Thông tin về chuỗi hành động: Ai (Actor) đang tương tác trên các màn hình cụ thể nào (<code>[W-...]</code>), chuỗi hành động diễn ra sao và kết quả cuối cùng là gì.</li><li>Dữ liệu chuyển giao giữa các màn hình (Key fields, values).</li><li>Xác nhận có hay không có xử lý ngầm (Background Logic Gate) sau khi lưu.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Sinh ra file Markdown có mã tiền tố <code>FLOW-*</code> (VD: <code>FLOW-AUTO-MESSAGE-BOOKING.md</code>) tuân thủ cấu trúc <strong>Đặc Tả Nghiệp Vụ Chuyên Sâu 6 Phần</strong>: <ol><li><code>## 1. Bối cảnh &amp; Ma trận Phân quyền Nghiệp vụ</code>: Trigger, vai trò người dùng và quyền hạn trên từng màn hình.</li><li><code>## 2. Chuỗi User Stories Đa Tầng</code>: Phân rã thành Setup Story, Primary Action Story, Tracking Story, và <strong>System Story</strong> (khi có xử lý ngầm).</li><li><code>## 3. Quy tắc Nghiệp vụ (Business Rules) &amp; Vòng đời Trạng thái</code>: Danh mục BR-* và bảng State Transition.</li><li><code>## 4. Đặc tả Chi tiết Hành trình Từng Chặng</code>: Thao tác chi tiết, Data Handoff liên màn hình, Kịch bản xử lý ngầm (so khớp, retry, idempotency) và Phản hồi trạng thái.</li><li><code>## 5. Ma trận Đối chiếu (Traceability Matrix)</code>: Đối chiếu 1-1 giữa User Story Step &lt;-&gt; Màn hình [W-*] &lt;-&gt; Sơ đồ Sequence &lt;-&gt; Thành phần kỹ thuật.</li><li><code>## 6. Sơ đồ Tuần tự Nghiệp vụ Liên Màn hình (Screen-to-Screen Sequence Diagram)</code>: Sơ đồ Mermaid mô tả rõ các màn hình cụ thể, thao tác người dùng, lưu trữ khái quát (DB Table, S3 Bucket) và phân đoạn <code>rect</code> xử lý ngầm (nếu có).</li></ol></li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Kỹ năng thiết kế các luồng quy trình nghiệp vụ (Business Process). Chú trọng vào chuỗi hành động xuyên suốt giữa các màn hình thay vì bị gò bó trong một API đơn lẻ.</li><li><strong>Quy tắc Phân tách 2 góc nhìn (2 Distinct Perspectives) BẮT BUỘC:</strong><ol><li><strong>Nhìn từ góc độ Giao diện (Kèm <code>/common</code> hoặc <code>surfaces</code>):</strong> Mô tả hành trình người dùng qua các màn hình cụ thể <code>[W-...]</code>. Chỉ nhắc tới lưu trữ (DB/S3) và Worker ngầm ở mức khái quát (tên table, tên bucket). Tuyệt đối <strong>CẤM</strong> nhét HTTP verbs (<code>POST /api/...</code>), SQL queries, DB internal column schema vào đây.</li><li><strong>Nhìn từ góc độ Kỹ thuật (Kèm <code>/architecture</code>):</strong> Vẽ sơ đồ tuần tự (Sequence Diagram) thể hiện TOÀN BỘ hệ thống ngầm, từ Backend Services, DB, Cronjobs, cho tới tích hợp 3rd party chuyên sâu. Lưu tại <code>architecture/03-business-process/</code>.</li></ol></li><li><strong>Cơ chế Background Logic (Tùy chọn):</strong><ul><li>Không phải flow nào cũng có background job. Khi có, bắt buộc phải có <strong>System Story</strong> và kịch bản lỗi/retry trong User Stories và phân đoạn <code>rect</code> trong sơ đồ Sequence Diagram.</li><li>Quản lý / cập nhật riêng phần logic ngầm: Sử dụng skill <code>/background-logic</code>.</li></ul></li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li>Được kích hoạt/khảo sát bởi <code>/grill</code>.</li><li>Kết hợp với <code>/background-logic</code> để cập nhật các tác vụ ngầm.</li><li>Có sự tương tác qua lại mật thiết với <code>/surfaces</code> và <code>/module</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/business-process</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const p=e(o,[["render",a]]);export{g as __pageData,p as default};
